  'S9NT-w05-quiz': {
    topic: 'Vòng hợp âm cơ bản (chord progression)',
    intro: 'Vì sao hàng nghìn bài hát nghe "quen quen"? Vì chúng dùng chung những vòng hợp âm kinh điển. Tuần này các em giải mã bí mật của các hit.',
    objectives: ['Hiểu khái niệm vòng hợp âm và cách ghi bằng số La Mã.', 'Thuộc vòng I — V — vi — IV và I — IV — V ở giọng Đô trưởng.', 'Nhận diện vòng hợp âm khi nghe nhạc đại chúng.'],
    theory: [
      { h: 'Vòng hợp âm là gì?' },
      { p: 'Vòng hợp âm (chord progression) là chuỗi các hợp âm nối tiếp nhau lặp đi lặp lại, tạo nên "bộ xương hoà thanh" của bài hát. Người ta ghi vòng hợp âm bằng số La Mã theo bậc của gam: I là hợp âm chủ, V là hợp âm át, vi là hợp âm bậc 6...' },
      { h: 'Các bậc hợp âm trong giọng Đô trưởng' },
      { ul: ['I = C (Đô trưởng) — hợp âm chủ, cảm giác về đích.', 'IV = F (Pha trưởng) — hạ át, mở rộng.', 'V = G (Son trưởng) — át, căng, muốn về I.', 'vi = Am (La thứ) — bậc 6 thứ, màu buồn nhẹ.'] },
      { h: 'Những vòng hợp âm kinh điển' },
      { p: 'Vòng I — V — vi — IV (ở giọng C: C — G — Am — F) được mệnh danh là "vòng hợp âm pop" vì xuất hiện trong vô số bản hit. Vòng I — IV — V (C — F — G) là nền tảng của dân ca, rock and roll và blues. Ngoài ra vòng Canon nổi tiếng từ bản Canon giọng Rê của Pachelbel cũng được nhạc nhẹ dùng lại rất nhiều.' },
      { h: 'Vì sao vòng hợp âm tạo cảm xúc?' },
      { p: 'Hoà thanh vận động theo quy luật căng — giãn: hợp âm V tạo độ căng, về I là thư giãn; vi mang màu buồn, IV gợi mở. Người viết nhạc sắp xếp chu kỳ căng — giãn này để dẫn dắt cảm xúc người nghe.' },
      { note: 'Thử ngay: bấm C — G — Am — F lặp lại trên đàn, rồi ngân nga vài giai điệu tuỳ ý — em sẽ thấy giai điệu nào nghe cũng "hợp lý" một cách kỳ lạ!' },
    ],
    examples: [
      { q: 'Viết vòng I — V — vi — IV ở giọng Son trưởng.', a: 'Giọng Son trưởng: I = G, V = D, vi = Em, IV = C. Vòng hợp âm: G — D — Em — C.' },
      { q: 'Vòng C — F — G — C thuộc dạng vòng nào? Cảm giác kết thúc ra sao?', a: 'Đây là vòng I — IV — V — I. Kết bằng V về I (G về C) tạo kết trọn vẹn, cảm giác bài hát khép lại chắc chắn, thoả mãn.' },
      { q: 'Nghe vòng F — G — Am ở giọng Đô trưởng — quy về số La Mã và giải thích màu cảm xúc.', a: 'F = IV, G = V, Am = vi. Vòng IV — V — vi: đi từ IV mở rộng, qua V căng lên, nhưng thay vì về I lại "lừa" sang vi (La thứ) — gọi là kết gãy (deceptive cadence), tạo cảm giác chưa trọn, man mác buồn, rất hay dùng cuối đoạn để kéo dài cảm xúc.' },
    ],
  },

